<script>
(() => { const body=document.getElementById('items-body'), options=document.getElementById('product-options').innerHTML, total=document.getElementById('grand-total'), source=document.getElementById('source'), supplier=document.getElementById('supplier-field');
function row(){const i=body.children.length; const tr=document.createElement('tr'); tr.innerHTML=`<td><select name="items[${i}][product_id]" class="form-select" required><option value="">Pilih produk</option>${options}</select></td><td><input name="items[${i}][quantity]" type="number" min="1" class="form-control qty" value="1" required></td><td><input name="items[${i}][unit_cost]" type="number" min="0" class="form-control cost" value="0" required></td><td class="subtotal">Rp 0</td><td><button type="button" class="btn btn-sm btn-outline-danger rounded-pill remove"><i class="fas fa-times"></i></button></td>`; body.appendChild(tr); tr.querySelectorAll('input').forEach(e=>e.addEventListener('input',calc)); tr.querySelector('.remove').addEventListener('click',()=>{tr.remove(); calc();});}
function calc(){let sum=0; body.querySelectorAll('tr').forEach(tr=>{const s=(+tr.querySelector('.qty').value||0)*(+tr.querySelector('.cost').value||0); sum+=s; tr.querySelector('.subtotal').textContent='Rp '+s.toLocaleString('id-ID');}); total.textContent='Rp '+sum.toLocaleString('id-ID');}
document.getElementById('add-item').addEventListener('click',row); source.addEventListener('change',()=>supplier.hidden=source.value!=='supplier'); row();
})();
</script>
